const response = await fetch("https://api.writer.com/v1/chat", {
  method: "POST",
  headers: {
    "Authorization": "Bearer $WRITER_API_KEY",
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    model: "palmyra-x-004",
    messages: [{ role: "user", content: "Hello!" }],
  }),
});
const data = await response.json();
